/* The opening pairs a short introduction with a working configuration example. */
.VPHome {
  margin-bottom: 0 !important;
}
.VPHomeHero {
  display: none;
}
.home-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 64px;
  align-items: center;
  max-width: 1208px;
  margin: 0 auto;
  padding: 80px 24px 60px;
}
.hero-copy {
  min-width: 0;
}
.hero-title {
  margin: 0;
  color: var(--vp-c-brand-1);
  font-size: clamp(2.5rem, 4.5vw, 3.75rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1.1;
}
.hero-meaning {
  margin: 12px 0 0;
  color: var(--vp-c-text-1);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1.25;
}
.hero-pronunciation {
  margin: 16px 0 0;
  color: var(--vp-c-text-2);
  font-size: 1rem;
  line-height: 1.5;
}
.hero-pronunciation strong {
  color: var(--vp-c-brand-1);
  font-weight: 600;
}
.hero-lede {
  max-width: 42ch;
  margin: 26px 0 0;
  color: var(--vp-c-text-2);
  font-size: 1.125rem;
  line-height: 1.7;
  text-wrap: pretty;
}
.hero-lede code {
  font-size: 0.9em;
  color: var(--vp-c-text-1);
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}
.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-height: 48px;
  padding: 10px 20px;
  border: 1px solid transparent;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 500;
  transition:
    background-color 0.15s,
    border-color 0.15s;
}
.action-btn-brand {
  color: var(--vp-button-brand-text);
  background: var(--vp-button-brand-bg);
}
.action-btn-brand:hover {
  background: var(--vp-button-brand-hover-bg);
}
.action-btn-alt {
  color: var(--vp-c-text-1);
  border-color: var(--vp-c-divider);
}
.action-btn-alt:hover {
  background: var(--vp-c-bg-soft);
  border-color: var(--vp-c-border);
}
.hero-install {
  display: flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  max-width: 100%;
  margin-top: 28px;
  padding: 0 0 0 12px;
  border: 1px solid var(--vp-c-divider);
  border-radius: 6px;
  font-size: 0.8125rem;
  background: var(--vp-c-bg-alt);
}
.hero-install code {
  overflow-wrap: anywhere;
}
.install-prompt {
  color: var(--vp-c-text-3);
}
.hero-install button {
  align-self: stretch;
  min-height: 44px;
  min-width: 62px;
  margin-left: 4px;
  padding: 6px 10px;
  border-left: 1px solid var(--vp-c-divider);
  color: var(--vp-c-text-2);
  font-size: 0.75rem;
}
.hero-install button:hover {
  color: var(--vp-c-brand-1);
  background: var(--vp-c-brand-soft);
}
.hero-install-note {
  margin-top: 10px;
  color: var(--vp-c-text-3);
  font-size: 0.8125rem;
}
.hero-install-note span {
  margin: 0 6px;
}
.hero-install-note a {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.hero-install-note a:hover {
  color: var(--vp-c-brand-1);
}
.hero-workbench {
  min-width: 0;
  border: 1px solid var(--vp-c-border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--vp-c-bg);
  box-shadow:
    0 12px 36px -20px #31152240,
    6px 6px 0 var(--vp-c-bg-soft);
}
.workbench-bar {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  background: var(--vp-c-bg-alt);
  border-bottom: 1px solid var(--vp-c-divider);
  font-size: 0.75rem;
  color: var(--vp-c-text-3);
}
.workbench-file {
  font-family: var(--vp-font-family-mono);
  color: var(--vp-c-text-1);
  font-size: 0.875rem;
}
.workbench-file span {
  margin-right: 8px;
  color: var(--vp-c-brand-1);
}
.workbench-select {
  display: flex;
  padding: 0 12px;
  border-bottom: 1px solid var(--vp-c-divider);
}
.workbench-select button {
  flex: 1;
  min-height: 48px;
  padding: 10px 8px;
  border-bottom: 2px solid transparent;
  font-size: 0.875rem;
  color: var(--vp-c-text-2);
}
.workbench-select button:hover {
  background: var(--vp-c-bg-soft);
}
.workbench-select button[aria-pressed="true"] {
  color: var(--vp-c-brand-1);
  border-color: var(--vp-c-brand-1);
}
.workbench-select button:focus-visible {
  outline-offset: -4px;
}
.workbench-config {
  min-height: 198px;
  padding: 22px;
  overflow-x: auto;
}
.workbench-comment {
  margin-bottom: 14px;
  color: var(--vp-c-text-3);
  font-family: var(--vp-font-family-mono);
  font-size: 0.75rem;
}
.hero-workbench pre {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.9;
}
.workbench-section {
  color: var(--vp-c-brand-1);
  font-weight: 500;
}
.workbench-equals {
  color: var(--vp-c-text-3);
}
.workbench-value {
  color: var(--vp-c-success-1);
}
.workbench-terminal {
  min-height: 170px;
  padding: 16px 22px 20px;
  background: #251d26;
  color: #f3eaf0;
  overflow-x: auto;
}
.workbench-terminal-label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 14px;
  color: #c5b2c3;
  font-size: 0.75rem;
}
.workbench-terminal-label span {
  font-family: var(--vp-font-family-mono);
}
.workbench-prompt {
  color: #ed9fbc;
}
.workbench-output {
  color: #b8d6a9;
}
.workbench-guide {
  display: flex;
  justify-content: space-between;
  padding: 12px 22px;
  border-top: 1px solid var(--vp-c-divider);
  color: var(--vp-c-text-2);
  font-size: 0.875rem;
}
.workbench-guide:focus-visible {
  outline-offset: -4px;
}
.workbench-guide:hover {
  color: var(--vp-c-brand-1);
  background: var(--vp-c-brand-soft);
}
.hero-footnote {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  max-width: 1160px;
  margin: 0 auto;
  padding: 20px 0;
  border-block: 1px solid var(--vp-c-divider);
  font-size: 0.8125rem;
  color: var(--vp-c-text-3);
}
.hero-footnote > span {
  color: var(--vp-c-text-2);
}
.hero-footnote ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.hero-footnote li::before {
  content: "·";
  margin-right: 8px;
  color: var(--vp-c-brand-1);
}
.landing-stations {
  margin-top: 56px;
  padding-top: 0;
  border-top: 0;
}
.landing-page .landing-stations h2 {
  max-width: 24ch;
}
.landing-page .migration-note {
  margin-top: 32px;
  padding-top: 20px;
  border-top: 1px solid var(--vp-c-divider);
  font-size: 0.875rem;
}
.station:hover {
  border-top-color: var(--vp-c-text-1);
}
.landing-page .card-link {
  letter-spacing: 0;
  text-transform: none;
}
@media (max-width: 1208px) {
  .hero-footnote {
    margin-inline: 24px;
  }
}
@media (max-width: 960px) {
  .home-hero {
    grid-template-columns: minmax(0, 1fr);
    max-width: 720px;
    gap: 40px;
    padding-top: 48px;
  }
  .hero-lede {
    max-width: 48ch;
  }
  .hero-footnote {
    justify-content: center;
    text-align: center;
  }
  .hero-footnote ul {
    justify-content: center;
  }
}
@media (max-width: 640px) {
  .home-hero {
    padding: 40px 24px;
    gap: 32px;
  }
  .hero-lede {
    font-size: 1rem;
  }
  .hero-actions {
    gap: 10px;
  }
  .action-btn {
    padding-inline: 16px;
    gap: 16px;
  }
  .workbench-bar {
    padding-inline: 16px;
  }
  .workbench-bar > span:last-child {
    display: none;
  }
  .workbench-select {
    padding-inline: 4px;
    flex-wrap: wrap;
  }
  .workbench-select button {
    font-size: 0.8125rem;
    padding-inline: 6px;
  }
  .workbench-config,
  .workbench-terminal {
    padding-inline: 16px;
  }
  .hero-footnote > span {
    display: none;
  }
  .hero-footnote ul {
    column-gap: 12px;
  }
  .landing-stations {
    margin-top: 40px;
  }
  .landing-pantry {
    padding-inline: 20px;
  }
  .landing-page .station-cmd {
    font-size: 0.875rem;
  }
  .landing-cta {
    padding-inline: 16px;
  }
}
<template>
  <DefaultTheme.Layout>
    <template #home-hero-info><span /></template>
    <template #home-hero-before><HomeHero /></template>
    <template #layout-bottom>
      <EndevSponsors />
      <EndevFooter />
    </template>
  </DefaultTheme.Layout>
</template>

<script setup lang="ts">
import DefaultTheme from "vitepress/theme";
import { onMounted } from "vue";
import EndevFooter from "./EndevFooter.vue";
import EndevSponsors from "./EndevSponsors.vue";
import HomeHero from "./HomeHero.vue";

onMounted(() => {
  // Drop the pre-paint sidebar layout after hydration has painted.
  requestAnimationFrame(() =>
    requestAnimationFrame(() =>
      document.documentElement.classList.remove("preboot", "preboot-sidebar"),
    ),
  );
});
</script>
